export function nativeCommand(lesson) {
  const path=`native/examples/${lesson.id}.cpp`;
  const flags=lesson.flags?` ${lesson.flags}`:'';
  return `run_dir=$(mktemp -d) && g++ -std=c++20 -Wall -Wextra -Werror ${path}${flags} -o "$run_dir/example" && (cd "$run_dir" && ./example)`;
}
